import { AuthenticationError } from "@formbricks/types/errors";
import { AccountSecurity } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/components/AccountSecurity";
import { DeleteAccount } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/components/DeleteAccount";
import { EditProfileDetailsForm } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/components/EditProfileDetailsForm";
import { SettingsCard } from "@/app/(app)/workspaces/[workspaceId]/settings/components/SettingsCard";
import {
  EMAIL_VERIFICATION_DISABLED,
  ENTERPRISE_LICENSE_REQUEST_FORM_URL,
  IS_FORMBRICKS_CLOUD,
  PASSWORD_RESET_DISABLED,
} from "@/lib/constants";
import { getOrganizationsWhereUserIsSingleOwner } from "@/lib/organization/service";
import { getUser } from "@/lib/user/service";
import { getTranslate } from "@/lingodotdev/server";
import { requiresPasswordConfirmationForAccountDeletion } from "@/modules/account/lib/account-deletion-auth";
import { getSession } from "@/modules/auth/lib/session";
import { LiteLicenseTip } from "@/modules/ee/license-check/components/lite-license-tip";
import { getEnterpriseLicense } from "@/modules/ee/license-check/lib/license";
import { getIsMultiOrgEnabled, getIsTwoFactorAuthEnabled } from "@/modules/ee/license-check/lib/utils";
import { getSettingsLayoutData } from "@/modules/settings/lib/navigation-data";
import { getOrganizationBillingPath } from "@/modules/settings/lib/routes";
import { IdBadge } from "@/modules/ui/components/id-badge";
import { PageContentWrapper } from "@/modules/ui/components/page-content-wrapper";
import { PageHeader } from "@/modules/ui/components/page-header";
import { UpgradePrompt } from "@/modules/ui/components/upgrade-prompt";

const Page = async () => {
  const isTwoFactorAuthEnabled = await getIsTwoFactorAuthEnabled();
  const isMultiOrgEnabled = await getIsMultiOrgEnabled();
  const t = await getTranslate();
  const session = await getSession();
  if (!session?.user) {
    throw new AuthenticationError(t("common.not_authenticated"));
  }

  const organizationsWithSingleOwner = await getOrganizationsWhereUserIsSingleOwner(session.user.id);
  const user = await getUser(session.user.id);
  if (!user) {
    throw new AuthenticationError(t("common.not_authenticated"));
  }

  // Two-factor upgrade points at the user's organization billing page (org-scoped after the refactor).
  const layoutData = await getSettingsLayoutData(session.user.id);
  const billingUpgradeHref = layoutData
    ? getOrganizationBillingPath(layoutData.organization.id, IS_FORMBRICKS_CLOUD)
    : "/";

  const canUseTwoFactorAuth = isTwoFactorAuthEnabled || user.twoFactorEnabled;
  // Self-hosted without any license key: 2FA is part of the free Lite license, so offer that instead
  // of the paid upgrade.
  const showTwoFactorLiteLicenseTip =
    !canUseTwoFactorAuth && !IS_FORMBRICKS_CLOUD && (await getEnterpriseLicense()).status === "no-license";

  let securityContent: React.ReactNode;
  if (canUseTwoFactorAuth) {
    securityContent = <AccountSecurity user={user} />;
  } else if (showTwoFactorLiteLicenseTip) {
    securityContent = (
      <LiteLicenseTip
        feature="two_factor_auth"
        title={t("workspace.settings.profile.two_factor_authentication_lite_license_title")}
        description={t("common.lite_license_tip_description")}
      />
    );
  } else {
    securityContent = (
      <UpgradePrompt
        title={t("workspace.settings.profile.unlock_two_factor_authentication")}
        description={t("workspace.settings.profile.two_factor_authentication_description")}
        buttons={[
          {
            text: IS_FORMBRICKS_CLOUD ? t("common.upgrade_plan") : t("common.request_trial_license"),
            href: IS_FORMBRICKS_CLOUD ? billingUpgradeHref : ENTERPRISE_LICENSE_REQUEST_FORM_URL,
          },
          {
            text: t("common.learn_more"),
            href: IS_FORMBRICKS_CLOUD
              ? billingUpgradeHref
              : "https://formbricks.com/learn-more-self-hosting-license?utm_source=formbricks-app&utm_medium=webapp&utm_campaign=ee_lock_two_factor",
          },
        ]}
      />
    );
  }

  const isPasswordResetEnabled = !PASSWORD_RESET_DISABLED && user.identityProvider === "email";
  const requiresPasswordConfirmation = requiresPasswordConfirmationForAccountDeletion(user);

  return (
    <PageContentWrapper>
      <PageHeader pageTitle={t("common.profile")} />
      <div>
        <SettingsCard
          title={t("workspace.settings.profile.personal_information")}
          description={t("workspace.settings.profile.update_personal_info")}>
          <EditProfileDetailsForm
            user={user}
            emailVerificationDisabled={EMAIL_VERIFICATION_DISABLED}
            isPasswordResetEnabled={isPasswordResetEnabled}
          />
        </SettingsCard>
        {user.identityProvider === "email" && (
          <SettingsCard
            title={t("common.security")}
            description={t("workspace.settings.profile.security_description")}
            bodyVariant={showTwoFactorLiteLicenseTip ? "bleed" : "padded"}>
            {securityContent}
          </SettingsCard>
        )}

        <SettingsCard
          title={t("workspace.settings.profile.delete_account")}
          description={t("workspace.settings.profile.confirm_delete_account")}>
          <DeleteAccount
            session={session}
            IS_FORMBRICKS_CLOUD={IS_FORMBRICKS_CLOUD}
            user={user}
            organizationsWithSingleOwner={organizationsWithSingleOwner}
            isMultiOrgEnabled={isMultiOrgEnabled}
            requiresPasswordConfirmation={requiresPasswordConfirmation}
          />
        </SettingsCard>
        <IdBadge id={user.id} label={t("common.profile_id")} variant="column" />
      </div>
    </PageContentWrapper>
  );
};

export default Page;

import { redirect } from "next/navigation";
import { getSession } from "@/modules/auth/lib/session";
import { SettingsShell } from "@/modules/settings/components/settings-shell";
import { getSettingsLayoutData } from "@/modules/settings/lib/navigation-data";

const AccountSettingsLayout = async ({ children }: Readonly<{ children: React.ReactNode }>) => {
  const session = await getSession();
  if (!session?.user) {
    return redirect("/auth/login");
  }

  const data = await getSettingsLayoutData(session.user.id);
  if (!data) {
    return redirect("/");
  }

  return <SettingsShell data={data}>{children}</SettingsShell>;
};

export default AccountSettingsLayout;

"use client";

import { useTranslation } from "react-i18next";
import { cn } from "@/lib/cn";
import { Badge } from "@/modules/ui/components/badge";
import { Button } from "@/modules/ui/components/button";
import { H4, Small } from "@/modules/ui/components/typography";

interface ButtonInfo {
  text: string;
  onClick: () => void;
  variant: "secondary" | "default" | "outline" | "ghost" | "link";
}

/**
 * How the card treats its body:
 * - `padded` — the default `px-4 pt-4` gutter, for ordinary form content.
 * - `bleed` — no gutter; the child supplies its own padding.
 * - `flush` — no gutter *and* no bottom padding, so edge-to-edge content (a table) meets the card's
 *   bottom border. Pairs with `overflow-hidden` on the card, which clips the content with the card's
 *   own inner radius — a `rounded-b-*` on the child would be off by the border width.
 */
export type TSettingsCardBodyVariant = "padded" | "bleed" | "flush";

const BODY_VARIANT_CLASSES: Record<TSettingsCardBodyVariant, string> = {
  padded: "px-4 pt-4",
  bleed: "",
  flush: "-mb-4",
};

export const SettingsCard = ({
  title,
  description,
  children,
  soon = false,
  bodyVariant = "padded",
  beta,
  className,
  buttonInfo,
  cta,
}: {
  title: string;
  description: string;
  children: any;
  soon?: boolean;
  bodyVariant?: TSettingsCardBodyVariant;
  beta?: boolean;
  className?: string;
  buttonInfo?: ButtonInfo;
  cta?: React.ReactNode;
}) => {
  const { t } = useTranslation();
  return (
    <div
      className={cn(
        "relative my-4 w-full max-w-4xl rounded-xl border border-slate-200 bg-white py-4 text-left shadow-xs",
        bodyVariant === "flush" && "overflow-hidden",
        className
      )}
      id={title}>
      <div className="flex justify-between border-b border-slate-200 px-4 pb-4">
        <div>
          <H4 className="font-medium tracking-normal">{title}</H4>
          <div className="ml-2">
            {beta && <Badge size="normal" type="warning" text="Beta" />}
            {soon && (
              <Badge size="normal" type="success" text={t("workspace.settings.enterprise.coming_soon")} />
            )}
          </div>
          <Small color="muted" margin="headerDescription">
            {description}
          </Small>
        </div>
        {cta ??
          (buttonInfo && (
            <Button type="button" onClick={buttonInfo?.onClick} variant={buttonInfo?.variant ?? "default"}>
              {buttonInfo?.text}
            </Button>
          ))}
      </div>
      <div className={BODY_VARIANT_CLASSES[bodyVariant]}>{children}</div>
    </div>
  );
};

"use client";

