"use client";

import { useTranslation } from "react-i18next";
import { TUser } from "@formbricks/types/user";
import { Button } from "@/modules/ui/components/button";

interface OrganizationMembership {
  organizationName: string;
  role: string;
}

interface DownloadMyDataButtonProps {
  readonly user: TUser;
  readonly organizationMemberships: readonly OrganizationMembership[];
}

export const DownloadMyDataButton = ({ user, organizationMemberships }: Readonly<DownloadMyDataButtonProps>) => {
  const { t } = useTranslation();

  const handleDownload = async () => {
    const data = {
      name: user.name,
      email: user.email,
      locale: user.locale,
      notificationSettings: user.notificationSettings,
      organizationMemberships: organizationMemberships.map((m) => ({
        organizationName: m.organizationName,
        role: m.role,
      })),
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "formbricks-user-data.json";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <Button variant="secondary" onClick={handleDownload}>
      {t("workspace.settings.profile.download_my_data")}
    </Button>
  );
